package com.fream.back.domain.m12.controller.command;

import com.fream.back.domain.m12.dto.Xxn30RequestDto;
import com.fream.back.domain.m12.entity.Xxn30;
import com.fream.back.domain.m12.exception.Xpb98Exception;
import com.fream.back.domain.m12.service.command.Xxn30CommandService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;




@Slf4j
@RestController
@RequestMapping("/shipments/seller")
@RequiredArgsConstructor
public class Xxn30CommandController {

    private final Xxn30CommandService sellerShipmentCommandService;







    @PostMapping
    public ResponseEntity<Long> createSellerShipment(
            @Validated @RequestBody Xxn30RequestDto requestDto
    ) {
        log.info("판매자 배송 정보 생성 요청: saleId={}, courier={}, trackingNumber={}",
                requestDto.getSaleId(), requestDto.getCourier(), requestDto.getTrackingNumber());

        try {
            Xxn30 shipment = sellerShipmentCommandService.createSellerShipment(
                    requestDto.getSaleId(),
                    requestDto.getCourier(),
                    requestDto.getTrackingNumber()
            );

            Long shipmentId = shipment.getId();
            log.info("판매자 배송 정보 생성 완료: shipmentId={}, saleId={}",
                    shipmentId, requestDto.getSaleId());

            return ResponseEntity.ok(shipmentId);

        } catch (Xpb98Exception e) {
            log.error("판매자 배송 정보 생성 실패 (Xpb98Exception): saleId={}, code={}, message={}",
                    requestDto.getSaleId(), e.getErrorCode().getCode(), e.getMessage());

            return ResponseEntity
                    .status(e.getErrorCode().getStatus())
                    .build();

        } catch (Exception e) {
            log.error("판매자 배송 정보 생성 실패 (일반 예외): saleId={}, error={}",
                    requestDto.getSaleId(), e.getMessage(), e);

            return ResponseEntity.badRequest().build();
        }
    }








    @PatchMapping("/{shipmentId}")
    public ResponseEntity<Void> updateShipment(
            @PathVariable Long shipmentId,
            @Validated @RequestBody Xxn30RequestDto requestDto
    ) {
        log.info("판매자 배송 정보 업데이트 요청: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());

        try {
            sellerShipmentCommandService.updateShipment(
                    shipmentId,
                    requestDto.getCourier(),
                    requestDto.getTrackingNumber()
            );

            log.info("판매자 배송 정보 업데이트 완료: shipmentId={}", shipmentId);
            return ResponseEntity.ok().build();

        } catch (Xpb98Exception e) {
            log.error("판매자 배송 정보 업데이트 실패 (Xpb98Exception): shipmentId={}, code={}, message={}",
                    shipmentId, e.getErrorCode().getCode(), e.getMessage());

            return ResponseEntity
                    .status(e.getErrorCode().getStatus())
                    .build();

        } catch (Exception e) {
            log.error("판매자 배송 정보 업데이트 실패 (일반 예외): shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);

            return ResponseEntity.badRequest().build();
        }
    }
}package com.fream.back.domain.m12.service.command;

import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m10.entity.Xgg74Status;
import com.fream.back.domain.m10.repository.Xgg74Repository;
import com.fream.back.domain.m12.entity.Xxn30;
import com.fream.back.domain.m12.entity.Xpb98Status;
import com.fream.back.domain.m12.exception.Xpb98ErrorCode;
import com.fream.back.domain.m12.exception.Xpb98Exception;
import com.fream.back.domain.m12.repository.Xxn30Repository;
import com.fream.back.domain.m07.service.command.Xnn94CommandService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;




@Slf4j
@Service
@RequiredArgsConstructor
public class Xxn30CommandService {

    private final Xxn30Repository sellerShipmentRepository;
    private final Xgg74Repository saleRepository;
    private final Xnn94CommandService warehouseStorageCommandService;










    @Transactional
    public Xxn30 createSellerShipment(Long saleId, String courier, String trackingNumber) {
        log.info("판매자 배송 정보 생성 시작: saleId={}, courier={}, trackingNumber={}",
                saleId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: saleId={}", saleId);
            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {

            Xgg74 sale = saleRepository.findById(saleId)
                    .orElseThrow(() -> new Xpb98Exception(
                            Xpb98ErrorCode.SALE_NOT_FOUND_FOR_SHIPMENT,
                            "해당 Sale을 찾을 수 없습니다: " + saleId
                    ));

            log.debug("판매 정보 조회: saleId={}, sellerId={}, currentStatus={}",
                    sale.getId(), sale.getSeller().getId(), sale.getStatus());


            Xxn30 shipment = Xxn30.builder()
                    .sale(sale)
                    .courier(courier)
                    .trackingNumber(trackingNumber)
                    .status(Xpb98Status.IN_TRANSIT)
                    .build();


            sale.assignSellerShipment(shipment);

            Xxn30 savedShipment = sellerShipmentRepository.save(shipment);
            log.info("판매자 배송 정보 저장 완료: shipmentId={}, saleId={}",
                    savedShipment.getId(), saleId);


            if (sale.isWarehouseStorage()) {
                log.info("창고 보관 상품 처리: saleId={}", saleId);


                warehouseStorageCommandService.createSellerStorage(sale, sale.getSeller());


                sale.updateStatus(Xgg74Status.IN_STORAGE);
                log.info("판매 상태 IN_STORAGE로 변경: saleId={}", saleId);
            }

            return savedShipment;

        } catch (Xpb98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("판매자 배송 정보 생성 실패: saleId={}, error={}", saleId, e.getMessage(), e);
            throw new Xpb98Exception(
                    Xpb98ErrorCode.SALE_NOT_FOUND_FOR_SHIPMENT,
                    "판매자 배송 정보 생성 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }










    @Transactional
    public Xxn30 updateShipment(Long shipmentId, String courier, String trackingNumber) {
        log.info("판매자 배송 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {
            Xxn30 sellerShipment = sellerShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new Xpb98Exception(
                            Xpb98ErrorCode.SELLER_SHIPMENT_NOT_FOUND,
                            "해당 Shipment를 찾을 수 없습니다: " + shipmentId
                    ));

            log.debug("판매자 배송 정보 조회: shipmentId={}, saleId={}, currentStatus={}",
                    sellerShipment.getId(),
                    sellerShipment.getSale().getId(),
                    sellerShipment.getStatus());

            sellerShipment.updateTrackingInfo(courier, trackingNumber);
            log.info("판매자 배송 정보 업데이트 완료: shipmentId={}", shipmentId);

            return sellerShipment;

        } catch (Xpb98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("판매자 배송 정보 업데이트 실패: shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);
            throw new Xpb98Exception(
                    Xpb98ErrorCode.SELLER_SHIPMENT_NOT_FOUND,
                    "판매자 배송 정보 업데이트 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }
}package com.fream.back.domain.m12.entity;

import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.global.entity.Xwb79Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity @jakarta.persistence.Table(name = "seller_shipment")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xxn30 extends Xwb79Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id", nullable = false)
    private Xgg74 sale;

    private String courier;
    private String trackingNumber;

    @Enumerated(EnumType.STRING)
    private Xpb98Status status;

    public void assignSale(Xgg74 sale) {
        this.sale = sale;
    }

    public void updateTrackingInfo(String courier, String trackingNumber) {
        this.courier = courier;
        this.trackingNumber = trackingNumber;
        this.status = Xpb98Status.IN_TRANSIT;
    }

    public void updateStatus(Xpb98Status newStatus) {
        if (this.status == null || this.status.canTransitionTo(newStatus)) {
            this.status = newStatus;
        } else {
            throw new IllegalStateException(
                    "Cannot transition from " + this.status + " to " + newStatus
            );
        }
    }
}

